// RemoveUser is the resolver for the removeUser field.
func (r *mutationResolver) RemoveUser(ctx context.Context, name string) (*model.RemovedUser, error) {
	user, err := r.UserStore.Remove(name)
	if err != nil {
		return nil, err
	}
	// The certificates are refused from now on anyway (identify finds no user), but revoked too: a user added again
	// by the same name starts without them.
	revoked, err := r.Enrollment.Registry.RevokeUser(user.Name, r.Now().UTC())
	if err != nil {
		return nil, fmt.Errorf("user %s removed, but its devices couldn't be revoked: %w", user.Name, err)
	}
	r.revoked(user.Name)
	if r.RemovedUser != nil {
		r.RemovedUser(user.Name)
	}
	log.Printf("Admin: removed user %s and revoked %d of its devices", user.Name, revoked)
	return &model.RemovedUser{Name: user.Name, RevokedDevices: revoked}, nil
}

// CreateEnrollmentCode is the resolver for the createEnrollmentCode field.
func (r *mutationResolver) CreateEnrollmentCode(ctx context.Context, user string) (*model.EnrollmentCode, error) {
	u := r.UserStore.Find(user)
	if u == nil {
		u = r.UserStore.FindByEmail(user)
	}
	if u == nil {
		return nil, fmt.Errorf("unknown user %q: add it first with ptt-server user add <email>", user)
	}
	if r.Config.MailOn() && u.Email == "" {
		return nil, fmt.Errorf("user %s has no email to mail the link to: ptt-server user email %s <email>", u.Name, u.Name)
	}
	code, expiresAt := r.Enrollment.Codes.Create(u.Name)
	result := &model.EnrollmentCode{User: u.Name, ExpiresAt: expiresAt}
	if r.Config.PublicURL != "" {
		result.ServerURL = &r.Config.PublicURL
	}
	if !r.Config.MailOn() {
		result.Code = &code
		return result, nil
	}
	if r.MailEnrollment == nil {
		return nil, errors.New("the server can't send mail")
	}
	if err := r.MailEnrollment(*u, code, expiresAt); err != nil {
		r.Enrollment.Codes.Redeem(code) // nobody got it
		return nil, fmt.Errorf("mailing the enrollment link to %s: %w", u.Email, err)
	}
	log.Printf("Admin: mailed an enrollment link for %s to %s", u.Name, u.Email)
	result.EmailedTo = &u.Email
	return result, nil
}

// RevokeDevice is the resolver for the revokeDevice field.
func (r *mutationResolver) RevokeDevice(ctx context.Context, serial string) (*enroll.Device, error) {
	device, err := r.Enrollment.Registry.RevokeDevice(strings.ToLower(serial), r.Now().UTC())
	if err != nil {
		return nil, err
	}
	r.revoked(device.User)
	log.Printf("Admin: revoked device %q of %s (serial %s)", device.Name, device.User, device.Serial)
	return &device, nil
}

